from app import pages

cases = [(0, 10, 0), (1, 10, 1), (9, 10, 1), (10, 10, 1), (11, 10, 2), (20, 10, 2), (21, 10, 3), (7, 1, 7), (10**100 + 1, 10, 10**99 + 1)]
for total, size, expected in cases:
    assert pages(total, size) == expected, (total, size, expected)
for total, size in [(-1, 10), (1, 0), (1, -1), (0, 0), (-1, -1)]:
    try:
        pages(total, size)
    except ValueError as exc:
        assert str(exc) == 'invalid pagination'
    else:
        raise AssertionError((total, size))
print('Passed 9 page-count cases and 5 validation cases.')
